public static void check(Solution solution) {
    assert Arrays.equals(solution.longestSubsequence(new int[]{3,0,-3,4,-5,0,-7,1}, -3), 3);
    assert Arrays.equals(solution.longestSubsequence(new int[]{1,2,3,4}, 1), 4);
    assert Arrays.equals(solution.longestSubsequence(new int[]{1,3,5,7}, 1), 1);
    assert Arrays.equals(solution.longestSubsequence(new int[]{1,1,1,1,1}, 0), 5);
    assert Arrays.equals(solution.longestSubsequence(new int[]{5,4,3,2,1}, -1), 5);
    assert Arrays.equals(solution.longestSubsequence(new int[]{1,3,5,7,9}, 2), 5);
